---
import Layout from '../layouts/Layout.astro';
import { successMessage, validateContact, type ContactErrors } from '../lib/contact';

let values = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success = '';

if (Astro.request.method === 'POST') {
  let data: FormData | undefined;
  try {
    data = await Astro.request.formData();
  } catch {
    data = undefined;
  }
  const read = (key: string) => {
    const value = data?.get(key);
    return typeof value === 'string' ? value : '';
  };
  const sent = { name: read('name'), email: read('email'), message: read('message') };
  errors = validateContact(sent);
  const valid = Object.keys(errors).length === 0;
  if (valid) success = successMessage(sent.name);

  if (Astro.request.headers.get('accept')?.includes('application/json')) {
    return Response.json(valid ? { ok: true, message: success } : { ok: false, errors }, {
      status: valid ? 200 : 400,
    });
  }

  if (!valid) {
    values = sent;
    Astro.response.status = 400;
  }
}
---

<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p class="success" id="contact-success" role="status">{success}</p>
  <form id="contact-form" method="post" action="/contact" novalidate>
    <div class="field">
      <label for="name">Name</label>
      <input
        id="name"
        name="name"
        type="text"
        value={values.name}
        aria-describedby="name-error"
        aria-invalid={errors.name ? 'true' : undefined}
      />
      <p class="error" id="name-error">{errors.name}</p>
    </div>
    <div class="field">
      <label for="email">Email</label>
      <input
        id="email"
        name="email"
        type="email"
        value={values.email}
        aria-describedby="email-error"
        aria-invalid={errors.email ? 'true' : undefined}
      />
      <p class="error" id="email-error">{errors.email}</p>
    </div>
    <div class="field">
      <label for="message">Message</label>
      <textarea
        id="message"
        name="message"
        rows="6"
        aria-describedby="message-error"
        aria-invalid={errors.message ? 'true' : undefined}>{values.message}</textarea
      >
      <p class="error" id="message-error">{errors.message}</p>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>

<script>
  import {
    successMessage,
    validateContact,
    type ContactErrors,
    type ContactField,
  } from '../lib/contact';

  const form = document.querySelector<HTMLFormElement>('#contact-form');
  const status = document.querySelector<HTMLElement>('#contact-success');
  const fields: ContactField[] = ['name', 'email', 'message'];

  function showErrors(errors: ContactErrors) {
    if (!form) return;
    for (const field of fields) {
      const control = form.elements.namedItem(field);
      const message = document.getElementById(`${field}-error`);
      if (message) message.textContent = errors[field] ?? '';
      if (control instanceof HTMLElement) {
        if (errors[field]) control.setAttribute('aria-invalid', 'true');
        else control.removeAttribute('aria-invalid');
      }
    }
  }

  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    const read = (key: string) => {
      const value = data.get(key);
      return typeof value === 'string' ? value : '';
    };
    const values = { name: read('name'), email: read('email'), message: read('message') };
    if (status) status.textContent = '';

    const errors = validateContact(values);
    showErrors(errors);
    if (Object.keys(errors).length > 0) {
      const first = fields.find((field) => errors[field]);
      const control = first && form.elements.namedItem(first);
      if (control instanceof HTMLElement) control.focus();
      return;
    }

    const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]');
    if (submit) submit.disabled = true;
    try {
      const response = await fetch(form.action, {
        method: 'POST',
        body: new URLSearchParams(values),
        headers: { Accept: 'application/json' },
      });
      const result: { ok: boolean; message?: string; errors?: ContactErrors } =
        await response.json();
      if (result.ok) {
        form.reset();
        if (status) status.textContent = result.message ?? successMessage(values.name);
      } else {
        showErrors(result.errors ?? {});
      }
    } catch {
      if (status) status.textContent = 'Your message could not be sent. Please try again.';
    } finally {
      if (submit) submit.disabled = false;
    }
  });
</script>
EOF
