s=open(p).read()
old="""      update();
      button.addEventListener"""
new="""      update();
      window.addEventListener('pageshow', () => {
        favorite = getFavorites().has(slug);
        update();
      });
      button.addEventListener"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
